(function(root){
const P=root.PLC||(typeof require==='function'?require('./engine.js'):null),L=root.LayoutLab||(typeof require==='function'?require('./layouts.js'):null);
function blank(){return {groups:[['EMPTY']],type:'OTE',out:'',preset:1};}
function validate(rows,l){if(!Array.isArray(rows)||rows.length>64)throw Error('Use at most 64 rungs.');const inputTags=Object.keys(L.inputs(l,L.fresh(l))),outs=L.outputs(l),mem=Array.from({length:16},(_,i)=>'M'+(i+1)),units=Array.from({length:8},(_,i)=>['T'+(i+1),'C'+(i+1)]).flat(),tags=new Set([...inputTags,...outs,...mem,...units.map(x=>x+'_DONE'),...units.filter(x=>x[0]==='T').map(x=>x+'_TIMING'),'EMPTY']);
 return rows.map((r,i)=>{if(!['OTE','OTL','OTU','TON','RTO','CTU','RES'].includes(r.type)||!Array.isArray(r.groups)||!r.groups.length||r.groups.length>8||r.groups.some(g=>!Array.isArray(g)||!g.length||g.length>4||g.some(t=>typeof t!=='string'||!tags.has(t.replace(/^!/,'')))))throw Error('Invalid contacts on rung '+(i+1));const timed=['TON','RTO','CTU','RES'].includes(r.type);if(r.out&&! (timed?units:[...outs,...mem]).includes(r.out))throw Error('Invalid output on rung '+(i+1));if(['TON','RTO'].includes(r.type)&&r.out&&!/^T/.test(r.out)||r.type==='CTU'&&r.out&&!/^C/.test(r.out))throw Error('Choose a timer T or counter C matching the instruction.');return {groups:r.groups.map(g=>g.slice()),type:r.type,out:r.out||'',preset:Math.max(.1,Math.min(999,Number(r.preset)||1))};});}
function scan(l,s,rows,plc,dt=.1){const inp=L.inputs(l,s),program={},rungs=rows.map((r,i)=>({groups:r.groups.map((g,j)=>g.map((t,k)=>{const id=`r${i}_${j}_${k}`;program[id]=t;return id;})),type:r.type,...(['TON','RTO','CTU','RES'].includes(r.type)?{unit:r.out||'UNASSIGNED',preset:r.preset}:{out:r.out||'UNASSIGNED'})}));P.scan({rungs},program,plc,inp,dt*1000);return Object.fromEntries(L.outputs(l).map(t=>[t,!!plc.bits[t]]));}
function check(l,rows){if(!rows.length||rows.some(r=>!r.out||r.groups.flat().some(t=>t==='EMPTY')))return {ok:false,message:'Add complete rungs. Choose every contact and output.'};try{validate(rows,l);}catch(e){return {ok:false,message:e.message};}
 const plant=L.fresh(l),plc=P.fresh();L.feed(l,plant);plant.run=true;let stopped=false,readyTest=false,faultTest=false;const allOutputsOff=c=>Object.values(c).every(v=>!v);
 for(let i=0;i<3600;i++){if(i===50)plant.run=false;if(i===60){stopped=true;plant.run=true;}if(i===120)plant.ready=false;if(i===130){readyTest=true;plant.ready=true;}if(i===200)plant.stations[l.nodes[0].id].fault=true;if(i===210){faultTest=true;plant.stations[l.nodes[0].id].fault=false;}
 const cmd=scan(l,plant,rows,plc);if((!plant.run||!plant.ready||L.inputs(l,plant).FAULT)&&!allOutputsOff(cmd))return {ok:false,message:!plant.run?'Stop test failed. All actuator outputs must turn off when RUN is off.':!plant.ready?'Ready test failed. Inhibit every actuator when READY is off.':'Fault test failed. Inhibit every actuator while FAULT is on.'};
 L.tick(l,plant,.1,true,cmd);if(plant.violations.length)return {ok:false,message:plant.violations[0]+'. Use mutually exclusive commands.'};if(plant.delivered>=6&&stopped&&readyTest&&faultTest)return {ok:true,message:'Correct. Six parts delivered, routes and lifts completed, and stop, ready, and fault tests passed.'};}
 return {ok:false,message:`Only ${plant.delivered} of 6 parts delivered in the simulated six minute test. Check station outputs, stop releases, lift limits, and route commands.`};}
root.LayoutPLC={blank,validate,scan,check,fresh:P.fresh};if(typeof module!=='undefined')module.exports=root.LayoutPLC;
})(typeof window==='undefined'?globalThis:window);
